// This recursive function searches for the 'error' key at any level
function findError(obj) {
  // If it's not an object, it can't have the key
  if (typeof obj !== 'object' || obj === null) {
    return null;
  }

  // If the key exists at the current level, return its value
  if (obj.hasOwnProperty('error')) {
    return obj.error;
  }

  // If not, search through all nested objects
  for (const key in obj) {
    if (obj.hasOwnProperty(key)) {
      const result = findError(obj[key]);
      // If found in a nested object, immediately return the result
      if (result !== null) {
        return result;
      }
    }
  }

  // If nothing was found after checking everything
  return null;
}

// Main logic
const item = $('When Executed by Another Workflow').first().json;

// Search for the error value in the entire item
const errorValue = findError(item);

// If an error was found...
if (errorValue !== null) {
  // ...return a NEW object with ONLY the error field
  return {
    json: {
      error: errorValue
    }
  };
} else {
  // If no 'error' field was found anywhere, discard this item
  return null;
}
